 app.post('/api/orders/:id/resend',sameOrigin,async(req,res)=>{
  const order=await accessOrder(req.params.id,String(req.body?.token||''));if(!order)return res.status(404).json({error:'Order not found.'});
  if(order.status!=='pending')return res.status(409).json({error:'This payment is no longer awaiting approval.'});
  const now=new Date();if(order.expiresAt<=now){await collections.orders.updateOne({_id:order._id,status:'pending'},{$set:{status:'expired',updatedAt:now}});await collections.inventory.updateMany({orderId:order._id,status:'held'},{$set:{status:'available'},$unset:{orderId:'',holdExpiresAt:''}});return res.status(409).json({error:'The payment hold expired. Start a new booking.'})}
  if(!hashpayAccount||!hashpayApiKey||!webhookSecret)return res.status(503).json({error:'Mobile money payments are unavailable right now.'});
  const count=Number(order.promptResendCount||0),last=order.lastPromptRequestAt?new Date(order.lastPromptRequestAt):new Date(order.promptSentAt||0);
  if(count>=3)return res.status(429).json({error:'You have used all three resend attempts. Please contact support.'});
  if(now-last<20000)return res.status(429).json({error:'Wait a few seconds before requesting another prompt.'});
  const lock=crypto.randomUUID(),locked=await collections.orders.updateOne({_id:order._id,status:'pending',$or:[{resendLockUntil:{$exists:false}},{resendLockUntil:{$lte:now}}]},{$set:{resendLock:lock,resendLockUntil:new Date(now.getTime()+20000),lastPromptRequestAt:now},$inc:{promptResendCount:1}});
  if(!locked.matchedCount)return res.status(409).json({error:'A payment prompt request is already in progress.'});
  try{const msisdn=String(order.phone||'').replace(/[^0-9]/g,'').replace(/^0/,'254'),push=await fetch('https://api.hashback.co.ke/initiatestk',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({api_key:hashpayApiKey,account_id:hashpayAccount,amount:String(order.amount),msisdn,reference:order.reference}),signal:AbortSignal.timeout(12000)}),d=await push.json().catch(()=>({}));if(!push.ok||!d.success||String(d.ResponseCode)!=='0'||!d.checkout_id)throw Error(d.message||d.ResponseDescription||'The M-Pesa prompt could not be sent. Try again.');await collections.orders.updateOne({_id:order._id,status:'pending',resendLock:lock},{$set:{checkoutId:d.checkout_id,merchantRequestId:d.MerchantRequestID||'',promptSentAt:new Date(),updatedAt:new Date()},$unset:{resendLock:'',resendLockUntil:''}});res.json({ok:true,promptResendCount:count+1,promptSentAt:new Date()})}
  catch(e){await collections.orders.updateOne({_id:order._id,status:'pending',resendLock:lock},{$set:{lastPromptError:String(e.message).slice(0,240)},$unset:{resendLock:'',resendLockUntil:''}});res.status(502).json({error:e.message||'Could not resend the prompt.'})}
 });
