async function accessOrder(id,token){if(!token)return null;return collections.orders.findOne({_id:String(id),accessHash:crypto.createHash('sha256').update(String(token)).digest('hex')})}
async function manualIssuePaidOrder(order,admin,receiptReference,note){
 const existing=await collections.tickets.find({orderId:order._id}).toArray();
 if(existing.length===order.items.length){await collections.inventory.updateMany({orderId:order._id,status:'held'},{$set:{status:'sold',soldAt:new Date()},$unset:{holdExpiresAt:'',manualHoldAt:''}});await collections.orders.updateOne({_id:order._id,status:'manual_processing'},{$set:{status:'paid',receipt:receiptReference,paidAt:new Date(),updatedAt:new Date(),paymentAudit:{source:'admin_manual',adminEmail:admin,receiptReference,note,at:new Date()}}});return existing}
 const assignments=Array(order.items.length).fill(null),used=new Set(),newlyHeld=[];
 await collections.inventory.updateMany({orderId:order._id,status:'held'},{$unset:{holdExpiresAt:''}});
 for(let i=0;i<order.items.length;i++){
  const item=order.items[i],oldTicket=existing.find(t=>Number(t.index)===i+1);
  if(oldTicket){assignments[i]=await collections.inventory.findOne({orderId:order._id,tierId:item.tierId,status:'sold',seatCode:oldTicket.seatCode})||null;continue}
  let inv=await collections.inventory.findOne({orderId:order._id,tierId:item.tierId,status:'held',_id:{$nin:Array.from(used)}});
  if(!inv){const base={eventId:order.eventId,tierId:item.tierId,status:'available'},preferred=item.seatCode&&item.seatCode!=='General admission'?item.seatCode:'';if(preferred){const r=await collections.inventory.findOneAndUpdate({...base,inventoryKey:preferred},{$set:{status:'held',orderId:order._id,manualHoldAt:new Date()}},{returnDocument:'after'});inv=r?.value||r}if(!inv){const r=await collections.inventory.findOneAndUpdate(base,{$set:{status:'held',orderId:order._id,manualHoldAt:new Date()}},{sort:{inventoryKey:1},returnDocument:'after'});inv=r?.value||r}if(inv)newlyHeld.push(inv._id)}
  if(!inv){if(newlyHeld.length)await collections.inventory.updateMany({_id:{$in:newlyHeld},orderId:order._id,status:'held'},{$set:{status:'available'},$unset:{orderId:'',manualHoldAt:''}});throw Error('No matching tickets remain in this tier. Resolve event capacity before approving payment.')}
  used.add(String(inv._id));assignments[i]=inv;
  await collections.tickets.updateOne({_id:String(order._id)+'-'+(i+1)},{$setOnInsert:{_id:String(order._id)+'-'+(i+1),orderId:order._id,memberId:order.memberId||null,index:i+1,ticketCode:crypto.randomBytes(9).toString('hex').toUpperCase(),eventId:order.eventId,eventTitle:order.eventTitle,eventCategory:order.eventCategory,venueName:order.venueName,venueTown:order.venueTown,startsAt:order.startsAt,attendee:{name:item.attendee.name,email:item.attendee.email},tierName:item.tierName,price:item.price,section:inv.section||item.section,seatCode:inv.seatCode||item.seatCode,gate:inv.gate||item.gate,receipt:receiptReference,status:'valid',createdAt:new Date(),inventoryId:inv._id,paymentAudit:{source:'admin_manual',adminEmail:admin,receiptReference,note}}},{upsert:true});
 }
 await collections.inventory.updateMany({orderId:order._id,status:'held'},{$set:{status:'sold',soldAt:new Date()},$unset:{holdExpiresAt:'',manualHoldAt:''}});
 await collections.orders.updateOne({_id:order._id,status:'manual_processing'},{$set:{items:order.items.map((item,i)=>({...item,seatCode:assignments[i]?.seatCode||item.seatCode,section:assignments[i]?.section||item.section,gate:assignments[i]?.gate||item.gate})),inventoryIds:assignments.filter(Boolean).map(x=>x._id),status:'paid',receipt:receiptReference,paidAt:new Date(),updatedAt:new Date(),paymentAudit:{source:'admin_manual',adminEmail:admin,receiptReference,note,at:new Date()}}});
 return collections.tickets.find({orderId:order._id}).sort({index:1}).toArray()
}
